add_action( 'woocommerce_after_checkout_form', 'perfectpixel_disable_enter_on_checkout' );

function perfectpixel_disable_enter_on_checkout() {
	?>
	<script>
	document.addEventListener( 'keydown', function ( e ) {
		if ( 'Enter' !== e.key ) {
			return;
		}
		var el = e.target;
		if ( el && el.form && el.form.classList.contains( 'checkout' ) && 'INPUT' === el.tagName && 'submit' !== el.type ) {
			e.preventDefault();
		}
	} );
	</script>
	<?php
}
